async function addStockMovement(data, studioId) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const mat = await getMaterialById(data.materialId, studioId);
  if (!mat) throw new TRPCError2({ code: "NOT_FOUND", message: "Material n\xE3o encontrado neste est\xFAdio." });
  const previousStock = parseFloat(String(mat.currentStock)) || 0;
  let newStock;
  if (data.type === "entrada") {
    newStock = previousStock + data.quantity;
  } else if (data.type === "saida") {
    newStock = Math.max(0, previousStock - data.quantity);
  } else {
    newStock = data.quantity;
  }
  await db.insert(stockMovements).values({
    materialId: data.materialId,
    type: data.type,
    quantity: String(data.quantity),
    previousStock: String(previousStock),
    newStock: String(newStock),
    reason: data.reason,
    notes: data.notes,
    createdBy: data.createdBy,
    createdAt: Date.now()
  });
  await db.update(materials).set({ currentStock: String(newStock) }).where(and(eq(materials.id, data.materialId), eq(materials.studioId, requireStockStudio(studioId))));
  return { previousStock, newStock };
}
