async function createPurchaseOrder(data, studioId) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  await assertStockSupplier(data.supplierId, studioId);
  for (const item of data.items) {
    if (!await getMaterialById(item.materialId, studioId)) throw new TRPCError2({ code: "NOT_FOUND", message: "Material n\xE3o encontrado neste est\xFAdio." });
  }
  const result = await db.insert(purchaseOrders).values({
    studioId: requireStockStudio(studioId),
    supplierId: data.supplierId,
    notes: data.notes,
    createdBy: data.createdBy,
    status: "rascunho"
  });
  const orderId = result[0].insertId;
  if (data.items.length > 0) {
    await db.insert(purchaseOrderItems).values(
      data.items.map((item) => ({
        orderId,
        materialId: item.materialId,
        quantity: String(item.quantity),
        unitPrice: String(item.unitPrice ?? 0),
        notes: item.notes
      }))
    );
  }
  return orderId;
}
