async function deletePurchaseOrder(id, studioId) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  await db.transaction(async (tx) => {
    const [order] = await tx.select({ id: purchaseOrders.id }).from(purchaseOrders).where(and(eq(purchaseOrders.id, id), eq(purchaseOrders.studioId, requireStockStudio(studioId)))).for("update");
    if (!order) throw new TRPCError2({ code: "NOT_FOUND", message: "Pedido n\xE3o encontrado neste est\xFAdio." });
    await tx.delete(purchaseOrderItems).where(eq(purchaseOrderItems.orderId, id));
    await tx.delete(purchaseOrders).where(and(eq(purchaseOrders.id, id), eq(purchaseOrders.studioId, studioId)));
  });
}
function buildWhatsAppOrderMessage(order) {
  const lines = [];
  lines.push("\u{1F6D2} *PEDIDO DE OR\xC7AMENTO*");
  lines.push(`\u{1F4CB} Fornecedor: ${order.supplierName ?? "N/A"}`);
  lines.push("");
  lines.push("*Itens solicitados:*");
  order.items.forEach((item, i) => {
    const qty = parseFloat(item.quantity);
    const price = parseFloat(item.unitPrice);
    const line = `${i + 1}. ${item.materialName ?? "Item"} \u2014 ${qty} ${item.materialUnit ?? "un"}`;
    lines.push(line + (price > 0 ? ` (R$ ${price.toFixed(2)}/un)` : ""));
    if (item.notes) lines.push(`   _${item.notes}_`);
  });
  if (order.notes) {
    lines.push("");
    lines.push(`\u{1F4DD} Observa\xE7\xF5es: ${order.notes}`);
  }
  lines.push("");
  lines.push("Por favor, envie o or\xE7amento com prazo de entrega. Obrigado! \u{1F64F}");
  return lines.join("\n");
}
