    if (row.classification === "quote_request") metrics.quotes++;
    if (row.classification === "reschedule") metrics.reschedules++;
    if (row.classification === "cancellation") metrics.cancellations++;
    if (row.classification === "waiting_information") metrics.waitingInformation++;
    if (row.classification === "reference_received") metrics.references++;
    if (row.classification === "high_purchase_intent") metrics.opportunities++;
    if (row.classification === "complaint") metrics.complaints++;
    if (row.priority === "HIGH" || row.priority === "URGENT") metrics.highPriority++;
