  const owner = ENV.authMode === "local" ? process.env.LOCAL_ADMIN_EMAIL ? await getUserByEmail(process.env.LOCAL_ADMIN_EMAIL) : null : ENV.ownerOpenId ? await getUserByOpenId(ENV.ownerOpenId) : null;
