import mysql13 from "mysql2/promise";
import { TRPCError as TRPCError26 } from "@trpc/server";
async function saveWhatsappConsent(input) {
  const c = await mysql13.createConnection({
    uri: process.env.DATABASE_URL,
    dateStrings: true
  });
  try {
    const [clients2] = await c.execute(
      "SELECT id,phone FROM clients WHERE id=? AND studioId=?",
      [input.clientId, input.studioId]
    );
    const [integrations] = await c.execute(
      "SELECT id FROM whatsapp_integrations WHERE id=? AND studio_id=?",
      [input.integrationId, input.studioId]
    );
    if (!clients2[0] || !integrations[0])
      throw new TRPCError26({
        code: "NOT_FOUND",
        message: "Cliente ou integra\xE7\xE3o n\xE3o encontrado neste est\xFAdio."
      });
    if (!clients2[0].phone)
      throw new TRPCError26({
        code: "BAD_REQUEST",
        message: "O cliente precisa ter telefone cadastrado."
      });
    const phone = normalizeBrazilianPhone(clients2[0].phone);
    const [lock] = await c.query(
      "SELECT GET_LOCK('tatuei-client-consent-index',10) AS acquired"
    );
    if (Number(lock[0]?.acquired) !== 1)
      throw new Error(
        "N\xE3o foi poss\xEDvel preparar a autoriza\xE7\xE3o. Tente novamente."
      );
    try {
      const [indexes] = await c.query(
        "SHOW INDEX FROM integration_contacts WHERE Key_name='integration_contacts_studio_phone_unique'"
      );
      if (indexes.length) {
        const columns = indexes.sort((a, b) => Number(a.Seq_in_index) - Number(b.Seq_in_index)).map((row) => row.Column_name);
        if (columns.join(",") !== "studio_id,normalized_phone")
          throw new Error("\xCDndice de autoriza\xE7\xE3o diferente do esperado.");
        await c.query(
          "ALTER TABLE integration_contacts DROP INDEX integration_contacts_studio_phone_unique, ADD INDEX integration_contacts_studio_phone_lookup (studio_id,normalized_phone)"
        );
      }
    } finally {
      await c.query("SELECT RELEASE_LOCK('tatuei-client-consent-index')");
    }
    const timestamp9 = (/* @__PURE__ */ new Date()).toISOString().slice(0, 19).replace("T", " ");
    await c.beginTransaction();
    await c.execute(
      "INSERT INTO integration_contacts(studio_id,integration_id,client_id,normalized_phone,has_whatsapp_opt_in,opt_in_at,opt_in_source,opted_out_at) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE integration_id=VALUES(integration_id),normalized_phone=VALUES(normalized_phone),has_whatsapp_opt_in=VALUES(has_whatsapp_opt_in),opt_in_at=VALUES(opt_in_at),opt_in_source=VALUES(opt_in_source),opted_out_at=VALUES(opted_out_at)",
      [
        input.studioId,
        input.integrationId,
        input.clientId,
        phone,
        input.enabled ? 1 : 0,
        input.enabled ? timestamp9 : null,
        input.enabled ? input.source : null,
        input.enabled ? null : timestamp9
      ]
    );
    const [saved] = await c.execute(
      "SELECT client_id,normalized_phone,has_whatsapp_opt_in FROM integration_contacts WHERE studio_id=? AND integration_id=? AND client_id=?",
      [input.studioId, input.integrationId, input.clientId]
    );
    if (saved.length !== 1 || saved[0].normalized_phone !== phone || Number(saved[0].has_whatsapp_opt_in) !== (input.enabled ? 1 : 0))
      throw new Error("A autoriza\xE7\xE3o n\xE3o foi salva no cliente selecionado.");
    await c.commit();
    return { ok: true };
  } catch (error) {
    await c.rollback();
    throw error;
  } finally {
    await c.end();
  }
}

