import { TRPCError as TRPCError27 } from "@trpc/server";
import { and as and29, eq as eq29 } from "drizzle-orm";
async function resolveManualRecipient(db, studioId, input) {
  let clientId = input.clientId;
  if (input.appointmentId != null) {
    const appointment = (await db.select({ clientId: appointments.clientId }).from(appointments).where(and29(eq29(appointments.id, input.appointmentId), eq29(appointments.studioId, studioId))).limit(1))[0];
    if (!appointment) throw new TRPCError27({ code: "NOT_FOUND", message: "Agendamento n\xE3o encontrado nesta empresa." });
    if (clientId != null && clientId !== appointment.clientId) {
      throw new TRPCError27({ code: "BAD_REQUEST", message: "O cliente n\xE3o corresponde ao agendamento." });
    }
    clientId = appointment.clientId;
  }
  if (!clientId) throw new TRPCError27({ code: "BAD_REQUEST", message: "Selecione um cliente cadastrado para enviar pela integra\xE7\xE3o." });
  const client = (await db.select({ id: clients.id, name: clients.name, phone: clients.phone }).from(clients).where(and29(eq29(clients.id, clientId), eq29(clients.studioId, studioId))).limit(1))[0];
  if (!client) throw new TRPCError27({ code: "NOT_FOUND", message: "Cliente n\xE3o encontrado nesta empresa." });
  let recipientPhone;
  let requestedPhone;
  try {
    recipientPhone = normalizeBrazilianPhone(client.phone ?? "");
    requestedPhone = normalizeBrazilianPhone(input.recipientPhone);
  } catch {
    throw new TRPCError27({ code: "BAD_REQUEST", message: "Informe um telefone brasileiro v\xE1lido com DDD no cadastro do cliente." });
  }
  if (recipientPhone !== requestedPhone) {
    throw new TRPCError27({ code: "BAD_REQUEST", message: "O telefone n\xE3o corresponde ao cadastro atual do cliente. Atualize o agendamento e tente novamente." });
  }
  return { clientId: client.id, recipientPhone, recipientName: client.name };
}

