function createIntegrationJobWorker(options = {}) {
  const processJobs = options.processJobs ?? processPendingIntegrationJobs;
  const initialDelayMs = options.initialDelayMs ?? 2500;
  const intervalMs = options.intervalMs ?? 15e3;
  const limit = options.limit ?? 20;
  const onError = options.onError ?? ((error) => console.error("[Messaging worker] Falha ao processar fila:", error));
  let started = false;
  let running = false;
  let timer;
  const schedule = (delay) => {
    timer = setTimeout(() => void tick(), delay);
    timer.unref?.();
  };
  const tick = async () => {
    if (!started) return;
    if (running) {
      schedule(intervalMs);
      return;
    }
    running = true;
    try {
      await processJobs(limit);
    } catch (error) {
      onError(error);
    } finally {
      running = false;
      if (started) schedule(intervalMs);
    }
  };
  return {
    start() {
      if (started) return;
      started = true;
      schedule(initialDelayMs);
    },
    stop() {
      started = false;
      if (timer) clearTimeout(timer);
      timer = void 0;
    },
    isRunning() {
      return running;
    }
  };
}
var integrationJobWorker = createIntegrationJobWorker();
function startIntegrationJobWorker() {
  if (isOutboundMessagingBlocked()) {
    console.log("[Messaging worker] Envio bloqueado neste ambiente; fila preservada.");
    return;
  }
  integrationJobWorker.start();
  console.log("[Messaging worker] Processamento da fila ativo a cada 15 segundos.");
}

